//! N0325: `recorder`, the screen-recording unit's state on its own, for clients that need
//! nothing else from `controls` (the bar's indicator). The daemon reads it from the user
//! manager's signals only while a client leases it; `controls.recorder` is unchanged.
use crate::control_center::Recorder;
use serde_json::json;
use std::collections::BTreeMap;

pub const TOPIC: &str = "recorder";

pub(crate) fn exports() -> BTreeMap<String, String> {
    let schema = serde_json::to_value(schemars::schema_for!(Recorder)).expect("schema");
    let types = format!(
        "-- Generated by nacre-protocol; do not edit. MIT OR Apache-2.0.\nexport type RecorderState = {}\nreturn {{}}\n",
        crate::artifacts::luau(&schema)
    );
    let frames = [
        json!({"t":"sub","topics":[TOPIC]}),
        json!({"t":"snap","topic":TOPIC,"seq":0,"data":{"recording":false}}),
        json!({"t":"patch","topic":TOPIC,"base":0,"seq":1,"data":{"recording":true}}),
        json!({"t":"patch","topic":TOPIC,"base":1,"seq":2,"data":{"recording":false}}),
    ];
    BTreeMap::from([
        (
            "protocol/schema/recorder-state.json".into(),
            serde_json::to_string_pretty(&schema).expect("schema") + "\n",
        ),
        ("protocol/luau/recorder.d.luau".into(), types),
        (
            "protocol/fixtures/recorder.jsonl".into(),
            frames
                .iter()
                .map(|frame| serde_json::to_string(frame).expect("fixture") + "\n")
                .collect(),
        ),
    ])
}
